function minCost(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  const cost = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  cost[0][0] = 0;
  let current = [[0, 0]];
  let changes = 0;

  while (current.length > 0) {
    const next = [];
    for (let k = 0; k < current.length; k++) {
      const [row, col] = current[k];
      if (cost[row][col] < changes) continue;
      for (let d = 0; d < 4; d++) {
        const r = row + directions[d][0];
        const c = col + directions[d][1];
        if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
        const step = grid[row][col] === d + 1 ? 0 : 1;
        if (changes + step < cost[r][c]) {
          cost[r][c] = changes + step;
          if (step === 0) current.push([r, c]);
          else next.push([r, c]);
        }
      }
    }
    current = next;
    changes++;
  }
  return cost[rows - 1][cols - 1];
}

