function minCost(grid) {
  // Relax every cell from its four neighbours until nothing improves (Bellman-Ford style).
  const m = grid.length, n = grid[0].length;
  const best = grid.map(row => row.map(() => Infinity));
  best[0][0] = 0;
  const moves = { 1: [0, 1], 2: [0, -1], 3: [1, 0], 4: [-1, 0] };
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      if (best[i][j] === Infinity) continue;
      for (const sign of [1, 2, 3, 4]) {
        const ni = i + moves[sign][0], nj = j + moves[sign][1];
        if (ni < 0 || nj < 0 || ni >= m || nj >= n) continue;
        const total = best[i][j] + (grid[i][j] === sign ? 0 : 1);
        if (total < best[ni][nj]) { best[ni][nj] = total; changed = true; }
      }
    }
  }
  return best[m - 1][n - 1];
}

