function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const mode = Math.floor(rand() * 3);
  // Mode 0: uniform signs. Mode 1: mostly right/down (cheap). Mode 2: mostly left/up (expensive).
  const sign = () => {
    if (mode === 0 || rand() < 0.25) return 1 + Math.floor(rand() * 4);
    return mode === 1 ? (rand() < 0.5 ? 1 : 3) : (rand() < 0.5 ? 2 : 4);
  };
  return [Array.from({ length: m }, () => Array.from({ length: n }, sign))];
}
